WITH cleaned AS (SELECT *, unit_price - quantity AS line_total FROM order_items WHERE unit_price <= 200), ranked AS (SELECT * FROM cleaned QUALIFY ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY quantity, id) = 1), enriched AS (SELECT a.id, a.order_id, a.product_id, a.line_total, d.amount, d.discount, d.status FROM ranked a LEFT JOIN orders d ON a.order_id = d.id), joined AS (SELECT src.id, src.order_id, src.product_id, src.line_total, src.amount, p.discount AS order_discount, p.shipping_fee FROM enriched src LEFT JOIN orders p ON src.order_id = p.id), scored AS (SELECT *, COUNT(order_discount) OVER w_part AS last4_count_order_discount, SUM(order_discount) OVER w_part AS last4_sum_order_discount, MIN(order_discount) OVER w_part AS last4_min_order_discount, AVG(order_discount) OVER w_part AS last4_avg_order_discount FROM joined WINDOW w_part AS (PARTITION BY order_id ORDER BY amount, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)), remaining_keys AS (SELECT product_id, order_id FROM scored EXCEPT ALL SELECT product_id, order_id FROM order_items WHERE unit_price > 240), verified AS (SELECT s.* FROM scored s INNER JOIN remaining_keys k ON s.product_id = k.product_id AND s.order_id = k.order_id), with_dims AS (SELECT e.*, p.product_name, p.launch_date, p.price FROM verified e INNER JOIN products p ON e.product_id = p.id) SELECT product_id, CASE WHEN order_discount >= 0.38 THEN 'HIGH' ELSE 'LOW' END AS order_discount_tier, PERCENTILE_APPROX(order_discount, 0.9) AS order_discount_p90, ROUND(AVG(last4_avg_order_discount), 2) AS avg_last4_avg_order_discount FROM with_dims GROUP BY ROLLUP (product_id, CASE WHEN order_discount >= 0.38 THEN 'HIGH' ELSE 'LOW' END)
